import NavLink from '@/components/common/NavLink'
import NavMenu from '@/components/nav/NavMenu'
import { isMenuActive } from '@/utils'
import { Flex, Image, Text } from '@chakra-ui/react'
import { useLocation } from 'react-router-dom'

import { IMenusProps } from '../type'

const PCMenus = ({ menus, logo, jump }: Pick<IMenusProps, 'menus' | 'logo' | 'jump'>) => {
  const { pathname } = useLocation()
  return (
    <Flex align="center" gap={{ lg: '32px', xl: '48px' }}>
      <Image src={logo?.image} h="32px" alt="logo" onClick={() => jump(logo?.url)} />
      <Flex align="center" gap="32px">
        {menus?.map(menu => {
          if ('children' in menu) {
            return (
              <NavMenu
                key={menu.title}
                title={menu.title}
                isActive={isMenuActive(menu as any, pathname)}
                list={menu.children}
                socials={menu.socials}
              />
            )
          } else {
            return (
              <NavLink key={menu.title} type={menu?.type} link={menu.path!} isActive={isMenuActive(menu as any, pathname)}>
                <Text color={isMenuActive(menu as any, pathname) ? 'text_caption' : 'primary_gray'} fontSize="15px" fontWeight="500">
                  {menu.title}
                </Text>
              </NavLink>
            )
          }
        })}
      </Flex>
    </Flex>
  )
}

export default PCMenus
