import { sdkMap } from './sdkFactory'
import { useSdkStore } from './useSdkStore'

export const useSdk = <T extends keyof typeof sdkMap>(sdkType: T) => {
  const { sdkFactory, isInitialized } = useSdkStore()
  if (!isInitialized) {
    console.warn('sdkType: ', sdkType, '####', 'SDK Factory is not initialized. Please wait for initialization.')
    return null
  }
  return sdkFactory.getSdk(sdkType)
}
